Definition so_id (so : stdout_st) : stdout_st := so.
Definition so_set (so : stdout_st) (_ : stdout_st) : stdout_st := so.

Lemma TT_exit_flush : forall (so : stdout_st) (T : TSet),
  (so_first so = false \/ so_buf so = []) -> zlength (so_buf so) <= 2^26 -> T [] ->
