Section XExit.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis AF_XIT : forall Σ m, ART RT Σ m -> xit_rt m.

Local Ltac ul := unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK in *; lia.

Theorem exit_ok : exit_contract RT XENVA OUT_repA ERR_repA.
